alter table public.viajes
  add column if not exists carta_porte_ctg text,
  add column if not exists carta_porte_nro_orden integer,
  add column if not exists carta_porte_estado text not null default 'PENDIENTE',
  add column if not exists carta_porte_emitida_at timestamptz,
  add column if not exists carta_porte_environment text,
  add column if not exists carta_porte_response jsonb,
  add column if not exists acoplado_vehiculo_id uuid;
do $$ begin if not exists(select 1 from pg_constraint where conname='viajes_acoplado_vehiculo_id_fkey') then alter table public.viajes add constraint viajes_acoplado_vehiculo_id_fkey foreign key(acoplado_vehiculo_id) references public.vehiculos(id) on delete set null; end if; end $$;
create index if not exists idx_viajes_carta_porte_ctg on public.viajes(carta_porte_ctg) where carta_porte_ctg is not null;
create index if not exists idx_viajes_transportista_estado on public.viajes(transportista_profile_id,estado);
create or replace function public.registrar_vehiculo_transportista(p_patente text,p_tipo text,p_capacidad_tn numeric default null) returns uuid language plpgsql security definer set search_path=public,auth,pg_temp as $$
declare v_uid uuid:=auth.uid(); v_transportista_id uuid; v_id uuid; v_tipo text:=upper(trim(coalesce(p_tipo,''))); v_patente text:=upper(regexp_replace(coalesce(p_patente,''),'[^A-Z0-9]','','g'));
begin if v_uid is null then raise exception 'AUTH_REQUIRED'; end if; if v_tipo not in ('CAMION','ACOPLADO') then raise exception 'TIPO_VEHICULO_INVALIDO'; end if; if length(v_patente)<6 or length(v_patente)>8 then raise exception 'PATENTE_INVALIDA'; end if; if p_capacidad_tn is not null and p_capacidad_tn<=0 then raise exception 'CAPACIDAD_INVALIDA'; end if; select id into v_transportista_id from public.transportistas where profile_id=v_uid and activo=true; if v_transportista_id is null then raise exception 'TRANSPORTISTA_PROFILE_REQUIRED'; end if; insert into public.vehiculos(transportista_id,patente,tipo,capacidad_tn,habilitado) values(v_transportista_id,v_patente,v_tipo,p_capacidad_tn,true) on conflict do nothing returning id into v_id; if v_id is null then select id into v_id from public.vehiculos where transportista_id=v_transportista_id and upper(regexp_replace(patente,'[^A-Z0-9]','','g'))=v_patente limit 1; end if; return v_id; end $$;
revoke all on function public.registrar_vehiculo_transportista(text,text,numeric) from public,anon; grant execute on function public.registrar_vehiculo_transportista(text,text,numeric) to authenticated;
create or replace function public.listar_vehiculos_transportista(p_operacion_id uuid,p_transportista_profile_id uuid) returns table(id uuid,patente text,tipo text,capacidad_tn numeric,habilitado boolean) language plpgsql stable security definer set search_path=public,auth,pg_temp as $$
declare v_transportista_id uuid; begin if auth.uid() is null or not public.usuario_puede_gestionar_logistica_operacion(p_operacion_id) then raise exception 'FORBIDDEN'; end if; select t.id into v_transportista_id from public.transportistas t where t.profile_id=p_transportista_profile_id and t.verificacion_estado='VERIFICADO' and t.activo=true; if v_transportista_id is null then raise exception 'TRANSPORTISTA_NOT_VERIFIED'; end if; return query select v.id,v.patente::text,v.tipo::text,v.capacidad_tn,v.habilitado from public.vehiculos v where v.transportista_id=v_transportista_id and v.habilitado=true order by v.tipo,v.patente; end $$;
revoke all on function public.listar_vehiculos_transportista(uuid,uuid) from public,anon; grant execute on function public.listar_vehiculos_transportista(uuid,uuid) to authenticated;
create or replace function public.crear_viaje_operacion_con_vehiculos(p_operacion_id uuid,p_transportista_profile_id uuid,p_vehiculo_id uuid,p_acoplado_vehiculo_id uuid,p_origen text,p_destino text,p_origen_nombre text,p_destino_nombre text) returns uuid language plpgsql security definer set search_path=public,auth,pg_temp as $$
declare v_id uuid; v_transportista_id uuid; v_verified text; v_patente text; v_acoplado text;
begin if auth.uid() is null or not public.usuario_puede_gestionar_logistica_operacion(p_operacion_id) then raise exception 'FORBIDDEN'; end if; select id,verificacion_estado into v_transportista_id,v_verified from public.transportistas where profile_id=p_transportista_profile_id and activo=true; if v_transportista_id is null or v_verified is distinct from 'VERIFICADO' then raise exception 'TRANSPORTISTA_NOT_VERIFIED'; end if; select patente::text into v_patente from public.vehiculos where id=p_vehiculo_id and transportista_id=v_transportista_id and habilitado=true and upper(tipo)='CAMION'; if v_patente is null then raise exception 'CAMION_NO_REGISTRADO_PARA_TRANSPORTISTA'; end if; if p_acoplado_vehiculo_id is not null then select patente::text into v_acoplado from public.vehiculos where id=p_acoplado_vehiculo_id and transportista_id=v_transportista_id and habilitado=true and upper(tipo)='ACOPLADO'; if v_acoplado is null then raise exception 'ACOPLADO_NO_REGISTRADO_PARA_TRANSPORTISTA'; end if; end if; insert into public.viajes(operacion_id,vehiculo_id,acoplado_vehiculo_id,origen,destino,estado,transportista_profile_id,asignado_por,origen_nombre,destino_nombre,patente_camion,patente_acoplado,creado_en,actualizado_at) values(p_operacion_id,p_vehiculo_id,p_acoplado_vehiculo_id,p_origen,p_destino,'ASIGNADO',p_transportista_profile_id,auth.uid(),p_origen_nombre,p_destino_nombre,v_patente,v_acoplado,now(),now()) returning id into v_id; insert into public.viaje_eventos(viaje_id,operacion_id,estado,lugar,empresa_nombre,observaciones,registrado_por) values(v_id,p_operacion_id,'CAMION_ASIGNADO',p_origen,p_origen_nombre,'Transportista, camión y acoplado seleccionados desde el registro de vehículos.',auth.uid()); return v_id; end $$;
revoke all on function public.crear_viaje_operacion_con_vehiculos(uuid,uuid,uuid,uuid,text,text,text,text) from public,anon; grant execute on function public.crear_viaje_operacion_con_vehiculos(uuid,uuid,uuid,uuid,text,text,text,text) to authenticated;
